const records = [
  { sku: 'VASE-DEMO-01', version: 'v2', title: 'Ceramic vase' },
  { sku: 'TABLE-DEMO-01', version: 'v3', title: 'Coffee table' },
  { sku: 'CHAIR-DEMO-01', version: 'v3', title: 'Armchair' },
];
const media = [
  { sku: 'TABLE-DEMO-01', version: 'v3', asset: 'coffee-table', approved: true },
  { sku: 'CHAIR-DEMO-01', version: 'v2', asset: 'armchair', approved: true },
  { sku: 'VASE-DEMO-01', version: 'v2', asset: 'vase', approved: true },
];
const key = row => JSON.stringify([row.sku, row.version]);
const mediaByKey = new Map(media.map(row => [key(row), row]));
if (mediaByKey.size !== media.length) throw new Error('Duplicate media key');
const joined = records.map(row => ({ ...row, asset: mediaByKey.get(key(row)) }));
const held = joined.filter(row => !row.asset?.approved);
if (held.length !== 1 || held[0].sku !== 'CHAIR-DEMO-01') throw new Error('Stale revision check failed');
return joined.filter(row => row.asset?.approved).map(row => ({
  json: {
    sku: row.sku, source_version: row.version, title: row.title,
    url: 'https://easyrender.ai/showcase/' + row.asset.asset + '.glb',
    heldForReview: held.map(record => record.sku),
  },
}));

const expected = $('Join draft inputs by SKU and version').all();
const mapped = [];
if ($input.all().length !== expected.length) throw new Error('Incomplete media download');
for (let i = 0; i < $input.all().length; i++) {
  const content = await this.helpers.getBinaryDataBuffer(i, 'data');
  const item = $('Join draft inputs by SKU and version').itemMatching(i).json;
  if (content.length < 20 || content.toString('ascii', 0, 4) !== 'glTF'
    || content.readUInt32LE(4) !== 2 || content.readUInt32LE(8) !== content.length) {
    throw new Error('Invalid GLB for ' + item.sku);
  }
  mapped.push({ json: { sku: item.sku, source_version: item.source_version, title: item.title,
    model_url: item.url, glb_bytes: content.length, publication_status: 'draft',
    heldForReview: item.heldForReview } });
}
return mapped;
